INSERT INTO games (slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured) VALUES
('hogwarts-legacy', 'Hogwarts Legacy', 'Live the unwritten and attend Hogwarts in the 1800s.', 'Your character is a student who holds the key to an ancient secret. Explore an open world of Hogwarts, Hogsmeade, and the surrounding highlands, learn spells, brew potions, tame magical beasts, and shape your own legacy in the wizarding world — a full century before Harry Potter''s story.', 'Avalanche Software', 'Warner Bros. Games', '2023-02-10', ARRAY['RPG','Action','Adventure'], ARRAY['Open World','Magic','Fantasy','Single-player','Story Rich'], ARRAY['Single-player','Controller Support','Achievements','Cloud Saves'], '/covers/hogwarts-legacy.hero.jpg', '/covers/hogwarts-legacy.box.jpg', 84, '$59.99', false),
('ghost-of-tsushima', 'Ghost of Tsushima', 'Become the Ghost in a stunning open-world samurai epic.', 'In 1274, a Mongol invasion has devastated Tsushima. As samurai Jin Sakai, you must forge a new path — breaking tradition to fight with stealth and cunning. With gorgeous wind-guided exploration and cinematic sword combat, this is one of the most beautiful games ever made.', 'Sucker Punch Productions', 'Sony Interactive Entertainment', '2020-07-17', ARRAY['Action','Adventure'], ARRAY['Open World','Samurai','Story Rich','Beautiful','Stealth'], ARRAY['Single-player','Controller Support','Photo Mode','Achievements'], '/covers/ghost-of-tsushima.hero.jpg', '/covers/ghost-of-tsushima.box.jpg', 83, '$59.99', true),
('persona-5-royal', 'Persona 5 Royal', 'A stylish JRPG about phantom thieves stealing corrupt hearts.', 'Lead a group of vigilante students who moonlight as the Phantom Thieves, entering a supernatural realm to change the hearts of corrupt adults. With razor-sharp style, a deep turn-based combat system, unforgettable characters, and a hundred hours of story, Persona 5 Royal is a modern JRPG landmark.', 'Atlus', 'Atlus', '2019-10-31', ARRAY['RPG','Adventure','Simulation'], ARRAY['Turn-Based','Anime','Story Rich','Stylish','School Life'], ARRAY['Single-player','Controller Support','Achievements'], '/covers/persona-5-royal.hero.jpg', '/covers/persona-5-royal.box.jpg', 95, '$59.99', false),
('devil-may-cry-5', 'Devil May Cry 5', 'Over-the-top stylish action from the masters of the genre.', 'Three demon hunters — Nero, Dante, and the mysterious V — wage war against the demonic invasion of Red Grave City. With impossibly fluid combat, deep style rankings, and pure arcade spectacle, DMC5 is the pinnacle of character-action games.', 'Capcom', 'Capcom', '2019-03-08', ARRAY['Action','Adventure'], ARRAY['Character Action','Stylish','Third-Person','Fast-Paced','Boss Fights'], ARRAY['Single-player','Online PvP','Controller Support','Achievements'], '/covers/devil-may-cry-5.hero.jpg', '/covers/devil-may-cry-5.box.jpg', 89, '$29.99', false),
('death-stranding', 'Death Stranding', 'Connect a fractured America as a legendary deliveryman.', 'In the aftermath of a catastrophe that blurred the line between life and death, sam porter Bridges crosses a hauntingly beautiful landscape to reconnect isolated cities. A one-of-a-kind journey about human connection, from the mind of Hideo Kojima.', 'Kojima Productions', 'Sony Interactive Entertainment', '2020-07-14', ARRAY['Adventure','Action'], ARRAY['Open World','Story Rich','Single-player','Sci-fi','Atmospheric'], ARRAY['Single-player','Async Multiplayer','Controller Support','Achievements'], '/covers/death-stranding.hero.jpg', '/covers/death-stranding.box.jpg', 82, '$19.99', false),
('left-4-dead-2', 'Left 4 Dead 2', 'The definitive four-player zombie co-op shooter.', 'Team up with three friends and blast through hordes of zombies in the legendary co-op shooter. With distinct special infected, endless replayability, and campaigns across the South, L4D2 remains the greatest zombie game ever made.', 'Valve', 'Valve', '2009-11-17', ARRAY['Shooter','Action'], ARRAY['Zombies','Co-op','FPS','Multiplayer','Classic'], ARRAY['Online Co-op','Local Co-op','Online PvP','Controller Support','Steam Workshop'], '/covers/left-4-dead-2.hero.jpg', '/covers/left-4-dead-2.box.jpg', 89, '$9.99', false),
('team-fortress-2', 'Team Fortress 2', 'Nine ridiculous classes, one legendary team-based shooter.', 'The comic, chaotic, endlessly influential hero shooter. Play as the Scout, the Spy, the Medic, and more in objective-based multiplayer mayhem. With decades of updates, an iconic art style, and a beloved community, TF2 is a true gaming institution.', 'Valve', 'Valve', '2007-10-10', ARRAY['Shooter','Action','Free to Play'], ARRAY['Multiplayer','PvP','Team-Based','Classes','Comedy'], ARRAY['Online PvP','Voice Chat','Steam Workshop','Leaderboards'], '/covers/team-fortress-2.hero.jpg', '/covers/team-fortress-2.box.jpg', 92, 'Free', false),
('garrys-mod', 'Garry''s Mod', 'A physics sandbox where the only limit is your imagination.', 'There are no goals — just you, a world of physics objects, and every tool you need. Play thousands of community-made game modes, from prop hunt to Trouble in Terrorist Town. Garry''s Mod is the ultimate creative playground and a party-game institution.', 'Facepunch Studios', 'Facepunch Studios', '2006-11-29', ARRAY['Sandbox','Indie'], ARRAY['Physics','Creative','Multiplayer','Modding','Comedy'], ARRAY['Single-player','Online Co-op','Online PvP','Steam Workshop'], '/covers/garrys-mod.hero.jpg', '/covers/garrys-mod.box.jpg', 88, '$9.99', false),
('rust', 'Rust', 'Survive, build, and betray in the world''s most brutal survival game.', 'Wake up naked on a beach with a rock and a torch. Gather, build, raid, and defend against a world of ruthless players in the multiplayer survival game that made betrayal an art form. Harsh, unforgiving, and endlessly compelling.', 'Facepunch Studios', 'Facepunch Studios', '2018-02-08', ARRAY['Survival','Action'], ARRAY['Multiplayer','PvP','Crafting','Open World','Base Building'], ARRAY['Online PvP','Online Co-op','Voice Chat','Cloud Saves'], '/covers/rust.hero.jpg', '/covers/rust.box.jpg', 86, '$39.99', false),
('ark-survival-evolved', 'ARK: Survival Evolved', 'Tame dinosaurs and survive a mysterious prehistoric world.', 'Wake up on a mysterious island filled with dinosaurs and other survivors. Tame and ride creatures from the T-rex to the dragon, build fortresses, craft technology, and uncover the mysteries of ARK — solo or with up to ten-player tribes.', 'Studio Wildcard', 'Studio Wildcard', '2017-08-29', ARRAY['Survival','Action','Adventure'], ARRAY['Dinosaurs','Multiplayer','Crafting','Open World','Taming'], ARRAY['Single-player','Online PvP','Online Co-op','Controller Support','Steam Workshop'], '/covers/ark-survival-evolved.hero.jpg', '/covers/ark-survival-evolved.box.jpg', 76, '$9.99', false),
('dead-by-daylight', 'Dead by Daylight', 'Four survivors, one killer — a multiplayer horror where every match is a slasher film.', 'One player becomes the Killer; four must repair generators and escape. With iconic horror villains like Michael Myers and Leatherface, tense cat-and-mouse gameplay, and years of new content, Dead by Daylight is the definitive asymmetric horror game.', 'Behaviour Interactive', 'Behaviour Interactive', '2016-06-14', ARRAY['Horror','Action','Multiplayer'], ARRAY['Asymmetric','PvP','Multiplayer','Stealth','Slasher'], ARRAY['Online PvP','Voice Chat','Controller Support','Cross-Platform Play'], '/covers/dead-by-daylight.hero.jpg', '/covers/dead-by-daylight.box.jpg', 80, '$19.99', false),
('the-sims-4', 'The Sims 4', 'The world-famous life simulator, where you create and control people.', 'Build homes, design personalities, pursue careers, start families, and tell stories with the most beloved life sim ever made. Free to play with a decade of add-on content, The Sims 4 lets you play with life in any way you can imagine.', 'Maxis', 'Electronic Arts', '2014-09-02', ARRAY['Simulation','Casual'], ARRAY['Life Sim','Creative','Building','Relaxing','Single-player'], ARRAY['Single-player','Controller Support','Cloud Saves','Gallery'], '/covers/the-sims-4.hero.jpg', '/covers/the-sims-4.box.jpg', 76, 'Free', false);

